package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Author   string `json:"author"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with optional filters
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")
	format := r.URL.Query().Get("fmt")

	if query == "" {
		http.Error(w, "Missing search query", 400)
		return
	}

	// Build search query with optional classification filter
	var sqlQuery string
	if classification != "" {
		// Classification filter is user-controlled - VULNERABLE
		sqlQuery = fmt.Sprintf(
			"SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) AND classification = '%s' ORDER BY ts_rank(to_tsvector('english', content), plainto_tsquery('english', $1)) DESC LIMIT 20",
			classification,
		)
	} else {
		sqlQuery = "SELECT id, title, content, author, classification FROM documents WHERE to_tsvector('english', content) @@ plainto_tsquery('english', $1) ORDER BY ts_rank(to_tsvector('english', content), plainto_tsquery('english', $1)) DESC LIMIT 20"
	}

	rows, err := db.Query(sqlQuery, query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.Author, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	if format == "pretty" {
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		enc.Encode(docs)
	} else {
		json.NewEncoder(w).Encode(docs)
	}
}

// exportDocument returns a single document by ID for PDF generation
func exportDocument(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	if idStr == "" {
		http.Error(w, "Missing id", 400)
		return
	}

	var d Document
	err := db.QueryRow(
		"SELECT id, title, content, author, classification FROM documents WHERE id = $1", idStr,
	).Scan(&d.ID, &d.Title, &d.Content, &d.Author, &d.Classify)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(d)
}

// healthCheck for load balancer probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	fmt.Fprint(w, "ok")
}

func loggingMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Redact potential injection attempts in logs
		safeQuery := strings.ReplaceAll(r.URL.RawQuery, "'", "[SQUOTE]")
		log.Printf("%s %s?%s from %s", r.Method, r.URL.Path, safeQuery, r.RemoteAddr)
		next(w, r)
	}
}

func main() {
	http.HandleFunc("/api/documents/search", loggingMiddleware(searchDocuments))
	http.HandleFunc("/api/documents/export", loggingMiddleware(exportDocument))
	http.HandleFunc("/healthz", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting document service on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
